import{_ as a,o,c as t,a4 as l}from"./chunks/framework.DzJZdBQK.js";const N=JSON.parse('{"title":"用 AI 写的一些小项目","description":"","frontmatter":{"date":"2025-12-23T11:25:30","title":"用 AI 写的一些小项目","categories":["教程100","写作","Solon","Solon 实用教程","AI"],"tags":["教程100","写作","Solon","Solon 实用教程","AI"]},"headers":[{"level":2,"title":"项目","slug":"项目","link":"#项目","children":[{"level":3,"title":"开发工具箱","slug":"开发工具箱","link":"#开发工具箱","children":[]},{"level":3,"title":"Java 模型转 SQL语句工具。","slug":"java-模型转-sql语句工具。","link":"#java-模型转-sql语句工具。","children":[]},{"level":3,"title":"流程编辑器","slug":"流程编辑器","link":"#流程编辑器","children":[]},{"level":3,"title":"表单编辑器","slug":"表单编辑器","link":"#表单编辑器","children":[]}]},{"level":2,"title":"体会","slug":"体会","link":"#体会","children":[]},{"level":2,"title":"Token 统计","slug":"token-统计","link":"#token-统计","children":[]}],"relativePath":"posts/course100/053.md","filePath":"posts/course100/053.md"}'),r={name:"posts/course100/053.md"};function i(d,e,n,s,c,p){return o(),t("div",null,[...e[0]||(e[0]=[l('<h2 id="项目" tabindex="-1">项目 <a class="header-anchor" href="#项目" aria-label="Permalink to &quot;项目&quot;">​</a></h2><p>近期通过 Claude Code cli 工具（使用的是 GLM 4.7 的模型）开发了一些项目，主体代码通过 AI 生成，人工做些调整。</p><h3 id="开发工具箱" tabindex="-1">开发工具箱 <a class="header-anchor" href="#开发工具箱" aria-label="Permalink to &quot;开发工具箱&quot;">​</a></h3><p>通过 go 语言实现，基于 fyne UI 框架开发工具箱，解决 DevHub 工具不够趁手时还要额外在网上查找在线工具的问题。如果想加功能就让 AI 生成，想加就能加，想用就能用。</p><p>项目地址：<a href="https://gitee.com/CrazyAirhead/dev-tools" target="_blank" rel="noreferrer">https://gitee.com/CrazyAirhead/dev-tools</a></p><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=NGIwYTViY2U5MGIyZDA1Mzc1YzQ5OThjZTVhYjgwNTFfR2s3RnRNY3UxY0Z5bEZyNVZsRXBicmk4Z1BERWtjQm9fVG9rZW46SVhvUWJnUFdRb1EzamF4bVdmR2MwOXc5bnFjXzE3NjY0NzEzODU6MTc2NjQ3NDk4NV9WNA" alt="img"></p><h3 id="java-模型转-sql语句工具。" tabindex="-1">Java 模型转 SQL语句工具。 <a class="header-anchor" href="#java-模型转-sql语句工具。" aria-label="Permalink to &quot;Java 模型转 SQL语句工具。&quot;">​</a></h3><p>通过 Java 语言实现，解决项目只有 Model，没有表结构时，系统无法启动问题，工具的想法来自 easy-query 的 CodeFirst 模式。</p><p>项目地址：<a href="https://gitee.com/CrazyAirhead/model-to-sql" target="_blank" rel="noreferrer">https://gitee.com/CrazyAirhead/model-to-sql</a></p><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=MWNmMDAwMDhlYzQxOTdhZTk5NWYwMDlhNjY2ZDRkMjNfR1VyT3Nqa244S0IxZXRLT2ZUdGFTTm5Sdm1iYUdGb05fVG9rZW46TkpQOGJ5RTdpb1hRNmd4ZW5zOWNMVjVBblljXzE3NjY0NzEzODU6MTc2NjQ3NDk4NV9WNA" alt="img"></p><h3 id="流程编辑器" tabindex="-1">流程编辑器 <a class="header-anchor" href="#流程编辑器" aria-label="Permalink to &quot;流程编辑器&quot;">​</a></h3><p>通过 Typescript 语言实现，基于Soybean Admin（使用 Navie UI 和 vue-flow），解决 Solon Flow 流程编排问题，支持撤回、恢复、自动布局、编辑属性等功能。</p><p>项目地址：<a href="https://gitee.com/CrazyAirhead/porpoise-flow" target="_blank" rel="noreferrer">https://gitee.com/CrazyAirhead/porpoise-flow</a> （未完成代码迁移，预留）</p><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=MjA4ODEyMTIwZWU0ZTRlZDEwNmUzMDM0YmQxNWNlZTNfTEhFWTV1ajhURTFoaEFMMUcwampIcTZMSzhUMkNiSHBfVG9rZW46T1dJV2JMTExUb3h5ZUt4M2pXYmNxdDkxbkJnXzE3NjY0NzEzODU6MTc2NjQ3NDk4NV9WNA" alt="img"></p><h3 id="表单编辑器" tabindex="-1">表单编辑器 <a class="header-anchor" href="#表单编辑器" aria-label="Permalink to &quot;表单编辑器&quot;">​</a></h3><p>项目基于 <a href="https://gitee.com/chengliang4810/naiveui-form-designer%EF%BC%8C" target="_blank" rel="noreferrer">https://gitee.com/chengliang4810/naiveui-form-designer，</a> 升级依赖的版本，并转换成 TypeScript 项目，为了能更好的集成到 Soybean Admin 中。</p><p>项目地址：<a href="https://gitee.com/CrazyAirhead/naiveui-form-designer" target="_blank" rel="noreferrer">https://gitee.com/CrazyAirhead/naiveui-form-designer</a></p><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=ZGY2ZmNmNDlmNDNlZWFkMjZkNGRkODAzNzYxY2YzNmFfMjVzU3FHdVdoVkpUQ0pvR2V0RDNPeHpvQ2NPdG5qRFVfVG9rZW46TlA5cGJBU2t6b3dGamx4UmZQTmNTSnVHbmw1XzE3NjY0NzEzODU6MTc2NjQ3NDk4NV9WNA" alt="img"></p><h2 id="体会" tabindex="-1">体会 <a class="header-anchor" href="#体会" aria-label="Permalink to &quot;体会&quot;">​</a></h2><ul><li>虽然自己当前使用 Claude Code（AI）的方法还是比较初级，很多东西也还是在摸索阶段。但 AI 已经能写很多自己之前不会的代码。不管怎么样，先用起来更重要。</li><li>AI 生成代码对于有代码基础的人会更友好一点。如果没基础的人员，还是应该补充的基础知识。</li><li>有的时候碰到一些问题不好描述，可以指定文件、代码片段、甚至是变量，而不只是描述界面要怎么样。</li><li>限制很重要，一开始需要选好技术框架，不要让AI自由发挥，并维护在 <code>CLAUDE.md</code> 中（如果没有生成的需要自己补充）。</li><li>虽然 Claude Code 没有像 <code>/init</code> 一样提供 <code>/update</code> 的命令，但可以直接在对话中说更新 <code>CLAUDE.md</code>，把一些代码上的调整更新到 <code>CLAUDE.md</code> 中。</li><li>AI 生成的一个好处，就是能先给你提供一些思路或者基础代码，这些可能会改变你的想法，接着可以调整 prompt和设计方案，用重新生成的方式再来一次，比起自己写了推倒重来，迭代的速度变快很多。</li></ul><h2 id="token-统计" tabindex="-1">Token 统计 <a class="header-anchor" href="#token-统计" aria-label="Permalink to &quot;Token 统计&quot;">​</a></h2><p>最近一个月的 token 统计，也不知道算不算多。</p><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=MGRhNWRkZjYwNGVjNjM4NDI4N2FmZTk1OWRlZDQ2MzJfOTFiM1JLSXdQWlRRNFZkRlZtNExjaDY4Nm1YT3Ntd2RfVG9rZW46UFMxdGJmQWo3bzlNZXN4U05WNmMzejlRbkdiXzE3NjY0NzEzODU6MTc2NjQ3NDk4NV9WNA" alt="img"></p><p>如果觉得 GLM-4.7 也还行，最近还有优惠活动。</p><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=OTVmNGE4NGE0ZGFmMmQ4MzM2YTdjYjhiOGM2MGU3ZjJfaDFqVHlraU5kanN0ZTR6MWMyRlBrY3BkdzloOHV3bkNfVG9rZW46Q0hNSWJkU2h0b3ZuSUp4N1kzOWNHNWh4blZiXzE3NjY0NzEzODU6MTc2NjQ3NDk4NV9WNA" alt="img"></p>',25)])])}const m=a(r,[["render",i]]);export{N as __pageData,m as default};
